package com.iot.firmware.auth

import java.security.MessageDigest
import java.util.concurrent.atomic.{AtomicInteger, AtomicLong}
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

// Circuit breaker states
sealed trait CircuitState
case object Closed extends CircuitState
case object Open extends CircuitState
case object HalfOpen extends CircuitState

class CircuitBreaker(
  val failureThreshold: Int = 5,
  val resetTimeoutMs: Long = 30000,
  val halfOpenMaxAttempts: Int = 1
) {
  @volatile private var state: CircuitState = Closed
  private val failureCount = new AtomicInteger(0)
  private val lastFailureTime = new AtomicLong(0)
  private val halfOpenAttempts = new AtomicInteger(0)

  def getState: CircuitState = {
    state match {
      case Open =>
        if (System.currentTimeMillis() - lastFailureTime.get() > resetTimeoutMs) {
          state = HalfOpen
          halfOpenAttempts.set(0)
          HalfOpen
        } else Open
      case other => other
    }
  }

  def recordSuccess(): Unit = {
    failureCount.set(0)
    state = Closed
  }

  def recordFailure(): Unit = {
    val count = failureCount.incrementAndGet()
    lastFailureTime.set(System.currentTimeMillis())
    if (count >= failureThreshold) {
      state = Open
    }
  }

  def allowRequest: Boolean = getState match {
    case Closed => true
    case HalfOpen => halfOpenAttempts.incrementAndGet() <= halfOpenMaxAttempts
    case Open => false
  }
}

// Device credential store - simulates firmware EEPROM storage
object DeviceCredentialStore {
  // Stored as (username -> password_hash) where hash = SHA-256(password)
  private var credentials: Map[String, Array[Byte]] = Map(
    "admin" -> hashCredential("admin", "s3cur3P@ss!"),
    "operator" -> hashCredential("operator", "0p3r@t0r!"),
    "readonly" -> hashCredential("readonly", "r3@d0nly!")
  )

  def hashCredential(username: String, password: String): Array[Byte] = {
    val digest = MessageDigest.getInstance("SHA-256")
    digest.update(username.getBytes("UTF-8"))
    digest.digest(password.getBytes("UTF-8"))
  }

  def getStoredHash(username: String): Option[Array[Byte]] = {
    credentials.get(username)
  }
}

// Authentication token for device-to-device communication
case class AuthToken(username: String, timestamp: Long, signature: Array[Byte])

// Main authentication service with circuit breaker protection
class DeviceAuthService(circuitBreaker: CircuitBreaker) {

  private val hmacKey = "iot-device-fw-key-2024".getBytes("UTF-8")

  // Authenticate using direct credential comparison
  def authenticateLocal(username: String, password: String): Either[String, AuthToken] = {
    if (!circuitBreaker.allowRequest) {
      return Left("AUTH_CIRCUIT_OPEN: Too many failures, try later")
    }

    val providedHash = DeviceCredentialStore.hashCredential(username, password)
    val storedHash = DeviceCredentialStore.getStoredHash(username)

    storedHash match {
      case Some(stored) if MessageDigest.isEqual(providedHash, stored) =>
        circuitBreaker.recordSuccess()
        Right(generateToken(username))
      case Some(_) =>
        circuitBreaker.recordFailure()
        Left("AUTH_FAILED: Invalid credentials")
      case None =>
        circuitBreaker.recordFailure()
        Left("AUTH_FAILED: Unknown device user")
    }
  }

  // Authenticate using pre-computed hash (for device-to-device mesh auth)
  // This allows devices to forward authentication without knowing plaintext
  def authenticateWithHash(username: String, credentialHash: Array[Byte]): Either[String, AuthToken] = {
    if (!circuitBreaker.allowRequest) {
      return Left("AUTH_CIRCUIT_OPEN: Too many failures, try later")
    }

    val storedHash = DeviceCredentialStore.getStoredHash(username)

    storedHash match {
      case Some(stored) if MessageDigest.isEqual(credentialHash, stored) =>
        circuitBreaker.recordSuccess()
        Right(generateToken(username))
      case Some(_) =>
        circuitBreaker.recordFailure()
        Left("AUTH_FAILED: Invalid credential hash")
      case None =>
        circuitBreaker.recordFailure()
        Left("AUTH_FAILED: Unknown device user")
    }
  }

  // Verify a token from another device in the mesh
  def verifyMeshToken(token: AuthToken): Boolean = {
    val expectedSig = computeHmac(s"${token.username}:${token.timestamp}")
    val timeDrift = Math.abs(System.currentTimeMillis() - token.timestamp)
    // Allow 5 minute time drift for IoT devices
    timeDrift < 300000 && MessageDigest.isEqual(token.signature, expectedSig)
  }

  private def generateToken(username: String): AuthToken = {
    val timestamp = System.currentTimeMillis()
    val signature = computeHmac(s"$username:$timestamp")
    AuthToken(username, timestamp, signature)
  }

  private def computeHmac(data: String): Array[Byte] = {
    val mac = Mac.getInstance("HmacSHA256")
    mac.init(new SecretKeySpec(hmacKey, "HmacSHA256"))
    mac.doFinal(data.getBytes("UTF-8"))
  }
}

// Mesh network protocol handler
class MeshProtocolHandler(authService: DeviceAuthService) {

  // Handle incoming mesh authentication request
  // Protocol: MESH_AUTH <username> <hex_encoded_hash>
  def handleMeshAuth(rawMessage: String): Either[String, AuthToken] = {
    val parts = rawMessage.split(" ")
    if (parts.length != 3 || parts(0) != "MESH_AUTH") {
      return Left("PROTOCOL_ERROR: Invalid mesh auth format")
    }

    val username = parts(1)
    val hashHex = parts(2)

    if (!username.matches("^[a-zA-Z0-9_]{1,32}$")) {
      return Left("PROTOCOL_ERROR: Invalid username format")
    }

    val credentialHash = hexToBytes(hashHex)
    if (credentialHash.isEmpty) {
      return Left("PROTOCOL_ERROR: Invalid hash encoding")
    }

    // Forward hash-based auth to the auth service
    authService.authenticateWithHash(username, credentialHash.get)
  }

  private def hexToBytes(hex: String): Option[Array[Byte]] = {
    if (hex.length % 2 != 0 || hex.length > 128) return None
    try {
      Some(hex.grouped(2).map(Integer.parseInt(_, 16).toByte).toArray)
    } catch {
      case _: NumberFormatException => None
    }
  }
}
